# -*- coding: utf-8 -*-
# 라디오·자연소리·휴식과 집중 위쪽 제목 새 디자인 (B안)
# ① 앱 아이콘 빼기 ② 제목(프리텐다드 SemiBold 600, 먹색, 18) + 오른쪽 작은 소리 막대를 한 묶음으로 가운데
# ③ 영문 부제 RADIO · NATURE SOUNDS · REST & FOCUS (Quicksand, 자간 1.6 고정, 은은한 회색, 가운데)
# ④ 위쪽 제목만 '자연소리'·'휴식과 집중' (홈 카드 이름은 그대로) — 16개 언어
# ⑤ SemiBold 글꼴(제목 글자만 담은 작은 파일 약 90KB)을 assets/fonts에 넣고 pubspec.yaml에 등록
import os, re, sys, json, base64
sys.stdout.reconfigure(encoding='utf-8')
W = os.path.join('lib', 'widgets', 'logo_shine.dart')
PUB = 'pubspec.yaml'
FONT = os.path.join('assets', 'fonts', 'PretendardTitle-SemiBold.otf')
D = os.path.join('lib', 'l10n')
FONT_B64 = ""
MENU = "/// 메뉴 첫 화면 위쪽 (라디오·자연소리·휴식과 집중): 제목(프리텐다드 SemiBold) + 오른쪽 작은 소리 막대를 한 묶음으로 가운데\n/// 아래에 작은 영문 부제(RADIO · NATURE SOUNDS · REST & FOCUS) — 나라별 라디오는 영문 대신 국기 + 나라 ▾\nclass MenuTitle extends StatelessWidget {\n  final String title; // 홈 카드 이름 (라디오 · 자연 · 휴식 · 집중) — 위쪽엔 전용 이름으로 바꿔 보여 줌\n  final String sub; // 홈 카드 설명\n  final bool isDark;\n  final Widget? subWidget; // 영문 부제 대신 넣을 것 (나라별 라디오: 국기 + 나라 ▾)\n  final VoidCallback? onTap; // 누르면 (나라별 라디오: 나라 고르기)\n  const MenuTitle({super.key, required this.title, required this.sub, required this.isDark, this.subWidget, this.onTap});\n\n  /// 위쪽 제목 (홈 카드 이름은 그대로 두고 여기만): 라디오 · 자연소리 · 휴식과 집중\n  String _headTitle() {\n    if (title == tr.catRadio) return tr.menuHeadRadio;\n    if (title == tr.catNature) return tr.menuHeadNature;\n    if (title == tr.catRest) return tr.menuHeadRest;\n    return title;\n  }\n\n  /// 영문 부제 — 제목이 이미 같은 영어면(Radio / RADIO) 같은 말 두 번 대신 PARANSORI\n  String? _capsFor(String head) {\n    String? c;\n    if (title == tr.catRadio) c = 'RADIO';\n    if (title == tr.catNature) c = 'NATURE SOUNDS';\n    if (title == tr.catRest) c = 'REST & FOCUS';\n    if (c == null) return null;\n    String letters(String s) => s.toUpperCase().replaceAll(RegExp(r'[^A-Z]'), '');\n    return letters(head) == letters(c) ? 'PARANSORI' : c;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    // 제목: 순검정 대신 부드러운 먹색 (다크는 크림색)\n    final ink = isDark ? const Color(0xFFF3EFE7) : const Color(0xFF2B2722);\n    final head = _headTitle();\n    final caps = subWidget == null ? _capsFor(head) : null;\n\n    // 제목 + 소리 막대 (한 묶음)\n    final titleRow = Row(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.end,\n      children: [\n        Flexible(\n          child: LogoShine(\n            base: ink,\n            glow: isDark ? const Color(0xFFA8A29A) : const Color(0xFF968F85),\n            child: Text(\n              head,\n              maxLines: 1,\n              overflow: TextOverflow.ellipsis,\n              textScaler: TextScaler.noScaling, // 로고처럼 글자 크기 설정과 상관없이 고정\n              style: TextStyle(\n                fontFamily: 'PretendardTitle',\n                fontWeight: FontWeight.w600,\n                fontSize: 18,\n                letterSpacing: -0.3,\n                height: 1.15,\n                color: ink,\n              ),\n            ),\n          ),\n        ),\n        const SizedBox(width: 6),\n        const Padding(\n          padding: EdgeInsets.only(bottom: 4), // 막대 바닥을 글자 바닥선에 맞춤\n          child: LogoEqBars(),\n        ),\n      ],\n    );\n\n    final col = Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.center,\n      children: [\n        titleRow,\n        const SizedBox(height: 3),\n        if (caps != null)\n          // 영문 부제: 작고 은은한 회색, 자간은 고정(지나치게 넓지 않게), 가운데\n          Text(\n            caps,\n            maxLines: 1,\n            textScaler: TextScaler.noScaling,\n            style: GoogleFonts.quicksand(\n              color: ink.withOpacity(0.45),\n              fontSize: 9,\n              height: 1.0,\n              letterSpacing: 1.6,\n              fontWeight: FontWeight.w700,\n            ),\n          )\n        else\n          // 나라별 라디오(국기 + 나라 ▾) 등: 길면 넘치지 않게 살짝 작아짐\n          FittedBox(\n            fit: BoxFit.scaleDown,\n            child: subWidget ??\n                Text(\n                  sub.replaceAll(RegExp(r'\\s*[\\x28（][^\\x29）]*[\\x29）]\\s*$'), ''),\n                  maxLines: 1,\n                  textScaler: TextScaler.noScaling,\n                  style: TextStyle(color: ink.withOpacity(0.5), fontSize: 11.5, height: 1.2),\n                ),\n          ),\n      ],\n    );\n    if (onTap == null) return col;\n    return GestureDetector(behavior: HitTestBehavior.opaque, onTap: onTap, child: col);\n  }\n}\n"
H = {'ko': ('라디오', '자연소리', '휴식과 집중'), 'en': ('Radio', 'Nature Sounds', 'Rest & Focus'), 'ja': ('ラジオ', '自然の音', '休息と集中'), 'zh': ('电台', '自然之声', '休息与专注'), 'zh_Hant': ('電台', '自然之聲', '休息與專注'), 'de': ('Radio', 'Naturklänge', 'Ruhe & Fokus'), 'es': ('Radio', 'Sonidos naturales', 'Descanso y enfoque'), 'fr': ('Radio', 'Sons de la nature', 'Repos & concentration'), 'it': ('Radio', 'Suoni della natura', 'Riposo & concentrazione'), 'pt': ('Rádio', 'Sons da natureza', 'Descanso e foco'), 'pl': ('Radio', 'Dźwięki natury', 'Odpoczynek i skupienie'), 'ru': ('Радио', 'Звуки природы', 'Отдых и фокус'), 'tr': ('Radyo', 'Doğa sesleri', 'Dinlenme ve odak'), 'id': ('Radio', 'Suara alam', 'Istirahat & fokus'), 'vi': ('Radio', 'Âm thanh thiên nhiên', 'Nghỉ ngơi & tập trung'), 'th': ('วิทยุ', 'เสียงธรรมชาติ', 'พักผ่อนและโฟกัส')}

for p in (W, PUB, D):
    if not os.path.exists(p):
        print('❌ 못 찾았어요:', p); sys.exit(1)
raw = open(W, 'rb').read().decode('utf-8')
crlf = '\r\n' in raw
s = raw.replace('\r\n', '\n')
if "fontFamily: 'PretendardTitle'" in s:
    print('이미 적용돼 있어요'); sys.exit(0)

# 1) logo_shine.dart: MenuTitle 통째로 새로
i = s.find('/// 메뉴 첫 화면 위쪽')
if i < 0 or 'class MenuTitle extends StatelessWidget' not in s[i:]:
    print('❌ MenuTitle을 못 찾았어요. 아무것도 저장 안 했어요.'); sys.exit(1)
s = s[:i] + MENU
if "import 'logo_eq_bars.dart';" not in s:
    s = s.replace("import '../utils/title_font.dart';\n", "import '../utils/title_font.dart';\nimport 'logo_eq_bars.dart';\n", 1)
for need in ("google_fonts/google_fonts.dart", "l10n/locale_holder.dart", "logo_eq_bars.dart"):
    if need not in s:
        print(f'❌ 불러오기({need})가 없어요. apply_menu_caps.py를 먼저 실행해 주세요. 아무것도 저장 안 했어요.'); sys.exit(1)
print('✔ 제목 새 디자인 (logo_shine.dart)')

# 2) pubspec.yaml: 글꼴 등록
pr = open(PUB, 'rb').read().decode('utf-8')
pnl = '\r\n' if '\r\n' in pr else '\n'
p2 = pr.replace('\r\n', '\n')
if 'family: PretendardTitle' not in p2:
    m = re.search(r'^([ \t]*)- family: Pretendard[ \t]*\n', p2, re.M)
    if not m:
        print('❌ pubspec.yaml에서 Pretendard 글꼴 자리를 못 찾았어요. 아무것도 저장 안 했어요.'); sys.exit(1)
    ind = m.group(1)
    add = (f'{ind}- family: PretendardTitle\n'
           f'{ind}  fonts:\n'
           f'{ind}    - asset: assets/fonts/PretendardTitle-SemiBold.otf\n'
           f'{ind}      weight: 600\n')
    p2 = p2[:m.start()] + add + p2[m.start():]
print('✔ pubspec.yaml 글꼴 등록')

# 3) 번역: 위쪽 제목 3개 (catRest 줄 다음에)
arbs = {}
for lang, (a, b, c) in H.items():
    p = os.path.join(D, f'app_{lang}.arb')
    if not os.path.exists(p):
        print(f'❌ {p} 파일이 없어요. 아무것도 저장 안 했어요.'); sys.exit(1)
    t = open(p, 'rb').read().decode('utf-8')
    if '"menuHeadRadio"' in t:
        continue
    nl = '\r\n' if '\r\n' in t else '\n'
    m = re.search(r'^([ \t]*)"catRest"\s*:\s*"(?:[^"\\]|\\.)*",[ \t]*\r?\n', t, re.M)
    if not m:
        print(f'❌ {lang}: catRest 줄을 못 찾았어요. 아무것도 저장 안 했어요.'); sys.exit(1)
    ind = m.group(1)
    add = ''.join(f'{ind}"{k}": {json.dumps(v, ensure_ascii=False)},{nl}' for k, v in
                  [('menuHeadRadio', a), ('menuHeadNature', b), ('menuHeadRest', c)])
    t2 = t[:m.end()] + add + t[m.end():]
    try:
        assert json.loads(t2)['menuHeadNature'] == b
    except Exception:
        print(f'❌ {lang}: 넣은 뒤 확인 실패. 아무것도 저장 안 했어요.'); sys.exit(1)
    arbs[p] = t2
print(f'✔ 번역 {len(arbs)}개 언어')

# 저장
if crlf: s = s.replace('\n', '\r\n')
open(W, 'wb').write(s.encode('utf-8'))
open(PUB, 'wb').write(p2.replace('\n', pnl).encode('utf-8'))
os.makedirs(os.path.dirname(FONT), exist_ok=True)
open(FONT, 'wb').write(base64.b64decode(FONT_B64))
for p, t2 in arbs.items():
    open(p, 'wb').write(t2.encode('utf-8'))
print('✔ 글꼴 파일 넣음 (assets/fonts/PretendardTitle-SemiBold.otf)')
print('저장했어요.')
